using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    <span class="rating-info">
        @if (AverageRating > 0)
        {
            <text>@AverageRating.ToString("0.0") (@RatingCount ratings)</text>
        }
        else
        {
            <text>No ratings yet</text>
        }
    </span>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private int _userRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating : _userRating;

    private void Rate(int stars)
    {
        _userRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
        var updated = RecipeService.GetById(RecipeId);
        if (updated is not null)
        {
            AverageRating = updated.AverageRating;
            RatingCount = updated.RatingCount;
        }
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 0.5rem 0;
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

.rating-info {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
}

.rating-thanks {
    margin-left: 0.5rem;
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 500;
}

