{"path": "/tmp/sv-66b6122ceebc44a38fed9c8c4182cf30/RecipeHub/Services/RecipeService.cs", "file_text": "using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted boiling water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra cheese.", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and spices.\n6. Add chicken and simmer 10 minutes.\n7. Serve with basmati rice or naan.", AverageRating = 4.7, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Mix tamarind paste, fish sauce, and sugar for sauce.\n4. Stir-fry noodles with sauce.\n5. Add tofu and bean sprouts.\n6. Serve with peanuts, lime, and green onions.", AverageRating = 4.3, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 10 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Stir in diced onion, tomato, jalapeño.\n4. Add lime juice, cilantro, garlic, and salt.\n5. Taste and adjust seasoning.\n6. Serve immediately with tortilla chips.", AverageRating = 4.6, RatingCount = 18 },
            new() { Id = 7, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nGreen onions", Steps = "1. Bring dashi stock to a simmer.\n2. Rehydrate wakame in water.\n3. Cube silken tofu.\n4. Dissolve miso paste in a ladle of warm broth.\n5. Add miso back to pot (do not boil).\n6. Add tofu and wakame.\n7. Serve topped with sliced green onions.", AverageRating = 4.1, RatingCount = 6 },
            new() { Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Scoop onto baking sheets.\n7. Bake at 375°F (190°C) for 9-11 minutes.", AverageRating = 4.9, RatingCount = 25 },
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
"}

