@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub - Share & Discover Recipes</PageTitle>

<div class="hero">
    <h1>🍳 RecipeHub</h1>
    <p class="lead">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/recipes/@category.ToLowerInvariant()" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <span class="category-name">@category</span>
        </a>
    }
</div>

<div class="cta-section">
    <h3>Have a recipe to share?</h3>
    <p>Join our community and share your favorite recipes with food lovers everywhere.</p>
    <a href="/submit" class="btn-submit">Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍣",
        "Desserts" => "🍪",
        _ => "🍽️"
    };
}

