    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

.lead {
    font-size: 1.2rem;
    color: #666;
}

.category-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 1rem;
