    border-radius: 4px;
    text-decoration: none;
    font-weight: 500;
}

.btn-submit:hover {
    background: #218838;
}

@page "/recipes/{Category}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeHub</PageTitle>

<nav>
    <a href="/">← Back to Categories</a>
</nav>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in _recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-meta">
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="recipe-rating">★ @recipe.AverageRating.ToString("0.0")</span>
                        <span class="recipe-count">(@recipe.RatingCount ratings)</span>
                    }
                    else
                    {
                        <span class="recipe-count">No ratings yet</span>
                    }
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

nav {
    margin-bottom: 1rem;
}

nav a {
    color: #0066cc;
    text-decoration: none;
}

nav a:hover {
    text-decoration: underline;
}

.recipe-list {
    display: grid;
    gap: 1rem;
    margin-top: 1rem;
}

.recipe-card {
    display: block;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.recipe-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.recipe-card h3 {
    margin: 0 0 0.5rem;
}

.recipe-meta {
    font-size: 0.9rem;
    color: #666;
}

.recipe-rating {
    color: #f5a623;
    font-weight: 600;
}

.recipe-count {
    margin-left: 0.25rem;
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@using RecipeHub.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

<nav>
    @if (_recipe is not null)
    {
        <a href="/recipes/@_recipe.Category.ToLowerInvariant()">← Back to @_recipe.Category</a>
    }
</nav>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge">@_recipe.Category</span>

    <StarRating RecipeId="@_recipe.Id"
                AverageRating="@_recipe.AverageRating"
                RatingCount="@_recipe.RatingCount" />

    <section class="recipe-section">
        <h2>🧾 Ingredients</h2>
        <ul>
            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>👩‍🍳 Steps</h2>
        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

nav {
    margin-bottom: 1rem;
}

nav a {
    color: #0066cc;
    text-decoration: none;
}

nav a:hover {
    text-decoration: underline;
}

.badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background: #e9ecef;
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 500;
    color: #495057;
}

.recipe-section {
    margin-top: 1.5rem;
}

.recipe-section h2 {
    font-size: 1.3rem;
    margin-bottom: 0.75rem;
}

.recipe-section ul {
    padding-left: 1.25rem;
}

.recipe-section li {
    margin-bottom: 0.3rem;
}

.recipe-section p {
    margin: 0.4rem 0;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="success-message">
        <h3>✅ Recipe submitted successfully!</h3>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added.</p>
        <a href="/">← Back to Home</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-control">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 600;
}

.form-control {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
}

.form-control:focus {
    border-color: #80bdff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.15);
}

.btn-submit {
    padding: 0.6rem 1.5rem;
    background: #28a745;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-submit:hover {
    background: #218838;
}

.success-message {
    padding: 1.5rem;
    background: #d4edda;
    border: 1px solid #c3e6cb;
    border-radius: 8px;
    margin-top: 1rem;
}

.success-message a {
    color: #0066cc;
    text-decoration: none;
}

::deep .validation-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

