toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@using RecipeHub.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

<nav>
    @if (_recipe is not null)
    {
        <a href="/recipes/@_recipe.Category.ToLowerInvariant()">← Back to @_recipe.Category</a>
    }
</nav>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge">@_recipe.Category</span>

    <StarRating RecipeId="@_recipe.Id"
                AverageRating="@_recipe.AverageRating"
                RatingCount="@_recipe.RatingCount" />

    <section class="recipe-section">
        <h2>🧾 Ingredients</h2>
        <ul>
            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>👩‍🍳 Steps</h2>
        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

